import torch

def check(name, make_bwd):
    class F(torch.autograd.Function):
        @staticmethod
        def forward(ctx, x):
            ctx.g = torch.ones_like(x)
            return x.sum()
        @staticmethod
        def backward(ctx, gout):
            return make_bwd(ctx, gout)
    x = torch.randn(16, requires_grad=True)
    y = F.apply(x)
    g = y.grad_fn.g
    y.backward()
    print(f"{name:35s} cloned: {x.grad.data_ptr() != g.data_ptr()}")

check("return ctx.g (ref kept)",        lambda ctx, go: (ctx.g,))
check("drop ctx ref first",             lambda ctx, go: (lambda t: (setattr(ctx, 'g', None), (t,))[1])(ctx.g))
check("return ctx.g * 1 (fresh)",       lambda ctx, go: (ctx.g * 1,))
check("no in-place mod, return ctx.g",  lambda ctx, go: (ctx.g,))
check("return contiguous()",            lambda ctx, go: (ctx.g.contiguous(),))
check("return view_as()",               lambda ctx, go: (ctx.g.view_as(ctx.g),))
check("return detach() of modified",    lambda ctx, go: (ctx.g.detach(),))
check("in-place mul_, drop ref",        lambda ctx, go: (lambda t: (t.mul_(go), setattr(ctx, 'g', None), (t,))[2])(ctx.g))

