import torch

class F(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x, w):
        ctx.gx = torch.ones_like(x)
        ctx.gw = torch.ones_like(w)
        return x.sum() * w.sum()
    @staticmethod
    def backward(ctx, gout):
        gx, gw = ctx.gx, ctx.gw
        gx.mul_(gout); gw.mul_(gout)
        return gx.detach(), gw.detach(), None

x = torch.randn(8, requires_grad=True)
w = torch.randn(8, requires_grad=True)
y = F.apply(x, w)
gx, gw = y.grad_fn.gx, y.grad_fn.gw
y.backward()
print("x.grad aliases gx:", x.grad.data_ptr() == gx.data_ptr())
print("w.grad aliases gw:", w.grad.data_ptr() == gw.data_ptr())
print("dtypes:", x.grad.dtype, w.grad.dtype, "values:", x.grad[:2], w.grad[:2])

